import{_ as l,a0 as r,w as p,s as o,ao as d,I as t,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智 | LCTT x X-CMD","titleTemplate":false,"description":"如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted","title":"如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智","tag":"202001","desc":""},"relativePath":"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted.md","filePath":"[post].md"}'),c={name:"202001/20190930 How the Linux screen tool can save your tasks - and your sanity - if SSH is interrupted.md"};function h(u,s,g,k,b,f){const n=r("Link");return p(),o("div",null,[s[15]||(s[15]=d(`<h1 id="如果-ssh-被中断-linux-screen-工具如何拯救你的任务以及理智" tabindex="-1">如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智 <a class="header-anchor" href="#如果-ssh-被中断-linux-screen-工具如何拯救你的任务以及理智" aria-label="Permalink to “如果 SSH 被中断，Linux screen 工具如何拯救你的任务以及理智”">​</a></h1><blockquote><p>当你需要确保长时间运行的任务不会在 SSH 会话中断时被杀死时，Linux screen 命令可以成为救生员。以下是使用方法。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/09/working_w_screen-shs-100812448-large.jpg" alt=""></p><p>如果因 SSH 会话断开而不得不重启一个耗时的进程，那么你可能会很高兴了解一个有趣的工具，可以用来避免此问题：<code>screen</code> 工具。</p><p><code>screen</code> 是一个终端多路复用器，它使你可以在单个 SSH 会话中运行多个终端会话，并随时从它们之中脱离或重新接驳。做到这一点的过程非常简单，仅涉及少数命令。</p><p>要启动 <code>screen</code> 会话，只需在 SSH 会话中键入 <code>screen</code>。 然后，你可以开始启动需要长时间运行的进程，并在适当的时候键入 <code>Ctrl + A Ctrl + D</code> 从会话中脱离，然后键入 <code>screen -r</code> 重新接驳。</p><p>如果你要运行多个 <code>screen</code> 会话，更好的选择是为每个会话指定一个有意义的名称，以帮助你记住正在处理的任务。使用这种方法，你可以在启动每个会话时使用如下命令命名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -S slow-build</span></span></code></pre></div><p>一旦运行了多个会话，要重新接驳到一个会话，需要从列表中选择它。在以下命令中，我们列出了当前正在运行的会话，然后再重新接驳其中一个。请注意，一开始这两个会话都被标记为已脱离。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -ls</span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>        6617.check-backups      (09/26/2019 04:35:30 PM)    (Detached)</span></span>
<span class="line"><span>        1946.slow-build         (09/26/2019 02:51:50 PM)    (Detached)</span></span>
<span class="line"><span>2 Sockets in /run/screen/S-shs</span></span></code></pre></div><p>然后，重新接驳到该会话要求你提供分配给会话的名称。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -r slow-build</span></span></code></pre></div><p>在脱离的会话中，保持运行状态的进程会继续进行处理，而你可以执行其他工作。如果你使用这些 <code>screen</code> 会话之一来查询 <code>screen</code> 会话情况，可以看到当前重新接驳的会话再次显示为 <code>Attached</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -ls</span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>        6617.check-backups      (09/26/2019 04:35:30 PM)    (Attached)</span></span>
<span class="line"><span>        1946.slow-build         (09/26/2019 02:51:50 PM)    (Detached)</span></span>
<span class="line"><span>2 Sockets in /run/screen/S-shs.</span></span></code></pre></div><p>你可以使用 <code>-version</code> 选项查询正在运行的 <code>screen</code> 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ screen -version</span></span>
<span class="line"><span>Screen version 4.06.02 (GNU) 23-Oct-17</span></span></code></pre></div><h3 id="安装-screen" tabindex="-1">安装 screen <a class="header-anchor" href="#安装-screen" aria-label="Permalink to “安装 screen”">​</a></h3><p>如果 <code>which screen</code> 未在屏幕上提供信息，则可能你的系统上未安装该工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which screen</span></span>
<span class="line"><span>/usr/bin/screen</span></span></code></pre></div><p>如果你需要安装它，则以下命令之一可能适合你的系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install screen</span></span>
<span class="line"><span>sudo yum install screen</span></span></code></pre></div><p>当你需要运行耗时的进程时，如果你的 SSH 会话由于某种原因断开连接，则可能会中断这个耗时的进程，那么 <code>screen</code> 工具就会派上用场。而且，如你所见，它非常易于使用和管理。</p><p>以下是上面使用的命令的摘要：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -S &lt;process description&gt;      开始会话</span></span>
<span class="line"><span>Ctrl+A Ctrl+D                        从会话中脱离</span></span>
<span class="line"><span>screen -ls                           列出会话</span></span>
<span class="line"><span>screen -r &lt;process description&gt;      重新接驳会话</span></span></code></pre></div><p>尽管还有更多关于 <code>screen</code> 的知识，包括可以在 <code>screen</code> 会话之间进行操作的其他方式，但这已经足够帮助你开始使用这个便捷的工具了。</p><hr>`,26)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3441777/how-the-linux-screen-tool-can-save-your-tasks-and-your-sanity-if-ssh-is-interrupted.html"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3441777/how-the-linux-screen-tool-can-save-your-tasks-and-your-sanity-if-ssh-is-interrupted.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const x=l(c,[["render",h]]);export{m as __pageData,x as default};
